struct MemberFormTests {
    @Test("member-form is refused to someone signed in without members.write")
    func refused() {
        #expect(Access.decide(permission: memberFormSchema.permission, session: Session(signedIn: true, permissions: [])) == .refused)
    }

    @Test("member-form sends someone signed out to sign in")
